package main

import (
	"bytes"
	"context"
	"encoding/binary"
	"fmt"
	"strings"

	"github.com/google/uuid"
	"github.com/xtls/xray-core/common"
	"github.com/xtls/xray-core/common/bitmask"
	"github.com/xtls/xray-core/common/buf"
	"github.com/xtls/xray-core/common/crypto"
	network "github.com/xtls/xray-core/common/net"
	"github.com/xtls/xray-core/common/protocol"
	"github.com/xtls/xray-core/proxy/shadowsocks"
	"github.com/xtls/xray-core/proxy/vmess"
	"github.com/xtls/xray-core/proxy/vmess/encoding"
)

func must(err error) {
	if err != nil {
		panic(err)
	}
}
type appendingAuthenticator struct {
	base crypto.Authenticator
}

func (a *appendingAuthenticator) NonceSize() int { return a.base.NonceSize() }
func (a *appendingAuthenticator) Overhead() int  { return a.base.Overhead() }
func (a *appendingAuthenticator) Open(dst, ciphertext []byte) ([]byte, error) {
	return a.base.Open(dst, ciphertext)
}
func (a *appendingAuthenticator) Seal(dst, plaintext []byte) ([]byte, error) {
	originalLen := len(plaintext)
	plaintext = append(plaintext, 0xa5)
	return a.base.Seal(dst, plaintext[:originalLen])
}

func appendingAEADIsolation() {
	aead := crypto.NewAesGcm(make([]byte, 16))
	newAuth := func() *crypto.AEADAuthenticator {
		return &crypto.AEADAuthenticator{
			AEAD: aead, NonceGenerator: crypto.GenerateAEADNonceWithSize(aead.NonceSize()),
			AdditionalDataGenerator: crypto.GenerateEmptyBytes(),
		}
	}
	plain := pattern(2*8174 + 1)
	snapshot := bytes.Clone(plain)
	var wire bytes.Buffer
	writer := crypto.NewAuthenticationWriter(&appendingAuthenticator{base: newAuth()}, crypto.PlainChunkSizeParser{}, &wire, protocol.TransferTypeStream, nil)
	must(writer.WriteMultiBuffer(buf.MultiBuffer{buf.FromBytes(plain)}))
	if !bytes.Equal(plain, snapshot) {
		panic("appending authenticator modified following/source plaintext")
	}
	reader := crypto.NewAuthenticationReader(newAuth(), crypto.PlainChunkSizeParser{}, bytes.NewReader(wire.Bytes()), protocol.TransferTypeStream, nil)
	var recovered bytes.Buffer
	must(buf.Copy(reader, buf.NewWriter(&recovered)))
	if !bytes.Equal(recovered.Bytes(), snapshot) {
		panic(fmt.Sprintf("appending authenticator changed frame boundaries: got=%d want=%d", recovered.Len(), len(snapshot)))
	}
	fmt.Println("actual AES-GCM wrapper append: 3 frames decrypt exactly; following frame and source preserved")
}


type observingSink struct {
	source   *buf.Buffer
	output   bytes.Buffer
	released bool
}

func (s *observingSink) Write(p []byte) (int, error) {
	s.released = s.source.Bytes() == nil
	return s.output.Write(p)
}

func sourceReleaseBeforeForwarding() {
	aead := crypto.NewAesGcm(make([]byte, 16))
	newAuth := func() *crypto.AEADAuthenticator {
		return &crypto.AEADAuthenticator{
			AEAD: aead, NonceGenerator: crypto.GenerateAEADNonceWithSize(aead.NonceSize()),
			AdditionalDataGenerator: crypto.GenerateEmptyBytes(),
		}
	}
	plain := pattern(3*8174 + 41)
	snapshot := bytes.Clone(plain)
	source := buf.NewWithSize(int32(len(plain)))
	copy(source.Extend(int32(len(plain))), plain)
	sink := &observingSink{source: source}
	writer := crypto.NewAuthenticationWriter(newAuth(), crypto.PlainChunkSizeParser{}, sink, protocol.TransferTypeStream, nil)
	must(writer.WriteMultiBuffer(buf.MultiBuffer{source}))
	if !sink.released || source.Bytes() != nil {
		panic(fmt.Sprintf("source remained retained during downstream forwarding: sinkObservedRelease=%t", sink.released))
	}
	for range 8 {
		recycled := buf.NewWithSize(int32(len(plain)))
		recycled.Release()
	}
	reader := crypto.NewAuthenticationReader(newAuth(), crypto.PlainChunkSizeParser{}, bytes.NewReader(sink.output.Bytes()), protocol.TransferTypeStream, nil)
	var recovered bytes.Buffer
	must(buf.Copy(reader, buf.NewWriter(&recovered)))
	if !bytes.Equal(recovered.Bytes(), snapshot) {
		panic("forwarded ciphertext changed after source release and buffer-pool churn")
	}
	fmt.Println("managed source released before downstream callback; owned ciphertext decrypts after pool churn")
}

func pattern(n int) []byte {
	b := make([]byte, n)
	for i := range b {
		b[i] = byte(i*31 + n)
	}
	return b
}

func inputBuffer(plain []byte, managed bool) *buf.Buffer {
	if !managed {
		return buf.FromBytes(plain)
	}
	b := buf.NewWithSize(int32(len(plain)))
	copy(b.Extend(int32(len(plain))), plain)
	return b
}

func inputBuffers(plain []byte, managed, multi bool) buf.MultiBuffer {
	if !multi {
		return buf.MultiBuffer{inputBuffer(plain, managed)}
	}
	mid := len(plain) / 2
	return buf.MultiBuffer{
		inputBuffer(plain[:mid], managed),
		inputBuffer(plain[mid:], managed),
	}
}

func payloadLimit(options bitmask.Byte) int {
	header, padding := 2, 0
	if options.Has(protocol.RequestOptionAuthenticatedLength) {
		header += 16
	}
	if options.Has(protocol.RequestOptionGlobalPadding) {
		padding = 64
	}
	return 8192 - 16 - header - padding
}

func checkVMessFrames(wire []byte, plainSize, payloadSize int, options bitmask.Byte) (int, int) {
	headerSize := 2
	if options.Has(protocol.RequestOptionAuthenticatedLength) {
		headerSize = 18
	}
	paddingEnabled := options.Has(protocol.RequestOptionGlobalPadding)
	frames := (plainSize + payloadSize - 1) / payloadSize
	base := plainSize + frames*(headerSize+16)
	if len(wire) < base || (paddingEnabled && len(wire) > base+frames*64) || (!paddingEnabled && len(wire) != base) {
		panic(fmt.Sprintf("VMess frame bytes out of bounds: payload=%d frames=%d wire=%d base=%d padding=%t", plainSize, frames, len(wire), base, paddingEnabled))
	}
	if options.Has(protocol.RequestOptionAuthenticatedLength) || options.Has(protocol.RequestOptionChunkMasking) {
		return frames, len(wire) - base
	}
	offset, remaining, totalPadding := 0, plainSize, 0
	for frame := range frames {
		chunk := min(remaining, payloadSize)
		if offset+headerSize > len(wire) {
			panic("truncated VMess length header")
		}
		encodedSize := int(binary.BigEndian.Uint16(wire[offset : offset+2]))
		frameSize := headerSize + encodedSize
		paddingSize := encodedSize - chunk - 16
		if frameSize > len(wire)-offset || paddingSize < 0 || (paddingEnabled && paddingSize > 64) || (!paddingEnabled && paddingSize != 0) {
			panic(fmt.Sprintf("invalid VMess frame: frame=%d size=%d padding=%d", frame, frameSize, paddingSize))
		}
		offset += frameSize
		remaining -= chunk
		totalPadding += paddingSize
	}
	if remaining != 0 || offset != len(wire) || totalPadding != len(wire)-base {
		panic(fmt.Sprintf("VMess frame sum mismatch: remaining=%d offset=%d wire=%d pad=%d", remaining, offset, len(wire), totalPadding))
	}
	return frames, totalPadding
}

func vmessRoundTrip(security protocol.SecurityType, options bitmask.Byte, n int, managed, multi bool) {
	user := &protocol.MemoryUser{Level: 0, Email: "round3@example.invalid"}
	account := &vmess.Account{Id: uuid.NewString()}
	var err error
	user.Account, err = account.AsAccount()
	must(err)
	request := &protocol.RequestHeader{
		Version: 1, User: user, Command: protocol.RequestCommandTCP,
		Address: network.DomainAddress("example.invalid"), Port: network.Port(443),
		Security: security, Option: options,
	}
	client := encoding.NewClientSession(context.Background(), 0)
	var encodedRequestHeader bytes.Buffer
	must(client.EncodeRequestHeader(request, &encodedRequestHeader))
	validator := vmess.NewTimedUserValidator()
	validator.Add(user)
	defer common.Close(validator)
	history := encoding.NewSessionHistory()
	defer common.Close(history)
	server := encoding.NewServerSession(validator, history)
	decodedRequest, err := server.DecodeRequestHeader(bytes.NewReader(encodedRequestHeader.Bytes()), false)
	must(err)
	plain := pattern(n)
	snapshot := bytes.Clone(plain)

	var requestWire bytes.Buffer
	requestWriter, err := client.EncodeRequestBody(request, &requestWire)
	must(err)
	must(requestWriter.WriteMultiBuffer(inputBuffers(plain, managed, multi)))
	if !bytes.Equal(plain, snapshot) {
		panic("VMess request writer modified caller plaintext")
	}
	requestFrames, requestPadding := checkVMessFrames(requestWire.Bytes(), n, payloadLimit(options), options)
	requestReader, err := server.DecodeRequestBody(decodedRequest, bytes.NewReader(requestWire.Bytes()))
	must(err)
	var requestRecovered bytes.Buffer
	must(buf.Copy(requestReader, buf.NewWriter(&requestRecovered)))
	if !bytes.Equal(requestRecovered.Bytes(), snapshot) {
		panic(fmt.Sprintf("VMess request mismatch security=%v options=%#x size=%d got=%d", security, options, n, requestRecovered.Len()))
	}

	var responseHeader bytes.Buffer
	server.EncodeResponseHeader(&protocol.ResponseHeader{}, &responseHeader)
	_, err = client.DecodeResponseHeader(bytes.NewReader(responseHeader.Bytes()))
	must(err)
	var responseWire bytes.Buffer
	responseWriter, err := server.EncodeResponseBody(decodedRequest, &responseWire)
	must(err)
	responsePlain := pattern(n)
	responseSnapshot := bytes.Clone(responsePlain)
	must(responseWriter.WriteMultiBuffer(inputBuffers(responsePlain, managed, multi)))
	if !bytes.Equal(responsePlain, responseSnapshot) {
		panic("VMess response writer modified caller plaintext")
	}
	responseFrames, responsePadding := checkVMessFrames(responseWire.Bytes(), n, payloadLimit(options), options)
	responseReader, err := client.DecodeResponseBody(request, bytes.NewReader(responseWire.Bytes()))
	must(err)
	var responseRecovered bytes.Buffer
	must(buf.Copy(responseReader, buf.NewWriter(&responseRecovered)))
	if !bytes.Equal(responseRecovered.Bytes(), responseSnapshot) {
		panic(fmt.Sprintf("VMess response mismatch security=%v options=%#x size=%d got=%d", security, options, n, responseRecovered.Len()))
	}
	fmt.Printf("vmess security=%v options=%#x size=%d managed=%t multi=%t reqFrames=%d reqPadding=%d respFrames=%d respPadding=%d request+response=ok\n", security, options, n, managed, multi, requestFrames, requestPadding, responseFrames, responsePadding)
}

func shadowsocksRoundTrip(kind shadowsocks.CipherType, n int, managed, multi bool) {
	account, err := (&shadowsocks.Account{CipherType: kind, Password: "round3 secret"}).AsAccount()
	must(err)
	memory := account.(*shadowsocks.MemoryAccount)
	iv := make([]byte, memory.Cipher.IVSize())
	for i := range iv {
		iv[i] = byte(i + 7)
	}
	plain := pattern(n)
	snapshot := bytes.Clone(plain)
	var encrypted bytes.Buffer
	writer, err := memory.Cipher.NewEncryptionWriter(memory.Key, iv, &encrypted)
	must(err)
	must(writer.WriteMultiBuffer(inputBuffers(plain, managed, multi)))
	if !bytes.Equal(plain, snapshot) {
		panic("Shadowsocks writer modified caller plaintext")
	}
	frames := (n + 8157) / 8158
	expectedWire := n + frames*34
	if encrypted.Len() != expectedWire {
		panic(fmt.Sprintf("Shadowsocks frame size mismatch: plaintext=%d frames=%d wire=%d expected=%d", n, frames, encrypted.Len(), expectedWire))
	}
	reader, err := memory.Cipher.NewDecryptionReader(memory.Key, iv, bytes.NewReader(encrypted.Bytes()))
	must(err)
	var recovered bytes.Buffer
	must(buf.Copy(reader, buf.NewWriter(&recovered)))
	if !bytes.Equal(recovered.Bytes(), snapshot) {
		panic(fmt.Sprintf("Shadowsocks mismatch cipher=%v size=%d got=%d", kind, n, recovered.Len()))
	}
	fmt.Printf("shadowsocks cipher=%v input=%d managed=%t multi=%t wire=%d frames=%d roundtrip=ok\n", kind, n, managed, multi, encrypted.Len(), frames)
}

func intermediateSealError() {
	aead := crypto.NewAesGcm(make([]byte, 16))
	calls := 0
	auth := &crypto.AEADAuthenticator{
		AEAD: aead,
		NonceGenerator: func() []byte {
			calls++
			if calls == 2 {
				return nil
			}
			return make([]byte, aead.NonceSize())
		},
	}
	var downstream bytes.Buffer
	writer := crypto.NewAuthenticationWriter(auth, crypto.PlainChunkSizeParser{}, &downstream, protocol.TransferTypeStream, nil)
	plain := pattern(2*8174 + 1)
	snapshot := bytes.Clone(plain)
	err := writer.WriteMultiBuffer(buf.MultiBuffer{buf.FromBytes(plain)})
	if err == nil || !strings.Contains(err.Error(), "invalid AEAD nonce size") || calls != 2 || downstream.Len() != 0 || !bytes.Equal(plain, snapshot) {
		panic(fmt.Sprintf("intermediate failure contract: err=%v nonceCalls=%d downstream=%d sourceUnchanged=%t", err, calls, downstream.Len(), bytes.Equal(plain, snapshot)))
	}
	fmt.Println("intermediate real-AEAD nonce error: second body seal fails, no partial downstream write, input unchanged")
}

func main() {
	for _, item := range []struct {
		security protocol.SecurityType
		options  bitmask.Byte
	}{
		{protocol.SecurityType_AES128_GCM, 0},
		{protocol.SecurityType_CHACHA20_POLY1305, 0},
		{protocol.SecurityType_AES128_GCM, protocol.RequestOptionChunkMasking | protocol.RequestOptionGlobalPadding},
		{protocol.SecurityType_AES128_GCM, protocol.RequestOptionAuthenticatedLength},
		{protocol.SecurityType_CHACHA20_POLY1305, protocol.RequestOptionChunkMasking | protocol.RequestOptionAuthenticatedLength | protocol.RequestOptionGlobalPadding},
	} {
		payloadSize := payloadLimit(item.options)
		for _, n := range []int{payloadSize - 1, payloadSize, payloadSize + 1, 8192, 3 * payloadSize, 3*payloadSize + 1} {
			for _, managed := range []bool{false, true} {
				vmessRoundTrip(item.security, item.options, n, managed, false)
			}
		}
	}
	for _, kind := range []shadowsocks.CipherType{shadowsocks.CipherType_AES_128_GCM, shadowsocks.CipherType_CHACHA20_POLY1305} {
		for _, n := range []int{8157, 8158, 8159, 8192, 3 * 8158, 3*8158 + 1} {
			for _, managed := range []bool{false, true} {
				shadowsocksRoundTrip(kind, n, managed, false)
			}
		}
	}
	vmessRoundTrip(protocol.SecurityType_AES128_GCM, 0, 8192, true, true)
	vmessRoundTrip(protocol.SecurityType_CHACHA20_POLY1305, 0, 8192, true, true)
	shadowsocksRoundTrip(shadowsocks.CipherType_AES_128_GCM, 8192, true, true)
	shadowsocksRoundTrip(shadowsocks.CipherType_CHACHA20_POLY1305, 8192, true, true)
	appendingAEADIsolation()
	sourceReleaseBeforeForwarding()
	intermediateSealError()
}
